selected.compute:
options=read('/input/options')
result=None
for count in reversed(range(goal['min_count'],goal['max_count']+1)):
    for group in combinations(options,count):
        ids=[row['id'] for row in group]
        if valid(ids):
            result=ids
            break
    if result is not None:
        break

selected.effects:
if exists('/output/selection'):
    selected=read('/output/selection')
else:
    write('/output/selection',result)
    selected=result
if receipt('report')=='success':
    pass
else:
    if receipt('report')=='unknown':
        status('report')
    if receipt('report')=='unattempted' or status('report')=='not_sent':
        send('report','team',selected)
if exists('/tmp/cache'):
    delete('/tmp/cache')
